/**
 * Generates a real page from Keter's pagination engine and exports its exact
 * PDF render plan for the Chromium visual/exportability prototype.
 *
 * This is a diagnostic fixture generated by the production layout code, not a
 * hand-written text sample. It deliberately does not change the production PDF
 * exporter.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { DocxImporter } from '../src/engine/docx-importer';
import { PaginationEngine } from '../src/engine/pagination-engine';
import { PdfExporter } from '../src/engine/pdf-exporter';
import type { PageGeometry } from '../src/types/typesetter';

const output = resolve(process.env.KETER_RENDER_PLAN ?? 'artifacts/keter-page-render-plan.json');
const geometry: PageGeometry = {
  pageWidth: 482,
  pageHeight: 680,
  marginTop: 48,
  marginBottom: 48,
  marginInside: 46,
  marginOutside: 42,
  isVerso: false,
};

// The sample content is passed through the same importer/sample model and
// pagination engine used by Keter; coordinates are not invented in this script.
const units = DocxImporter.getSampleBerakhot();
const document = PaginationEngine.paginateDocument({
  title: 'Keter real layout PDF diagnostic',
  layoutType: 'rav_text',
  units,
  geometry,
  enableOrnaments: false,
});

if (!document.pages.length) throw new Error('Keter pagination returned no pages');
const page = document.pages[0];
const plan = PdfExporter.buildPageRenderPlan(page);
const words = plan.lines.flatMap(line => line.words);
if (!words.length) throw new Error('Keter render plan contains no words');

const payload = {
  source: 'PaginationEngine.paginateDocument + PdfExporter.buildPageRenderPlan',
  layoutType: page.layoutType,
  geometry: page.geometry,
  pageNumber: page.pageNumber,
  headerTitle: page.headerTitle,
  plan,
};
await mkdir(resolve(output, '..'), { recursive: true });
await writeFile(output, JSON.stringify(payload), 'utf8');
console.log(JSON.stringify({
  output,
  pageNumber: page.pageNumber,
  pageSizePt: [page.geometry.pageWidth, page.geometry.pageHeight],
  lines: plan.lines.length,
  words: words.length,
  markedWords: words.filter(w => /[\u0591-\u05C7]/u.test(w.text)).length,
  source: payload.source,
}, null, 2));
